const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const q = $('Gate link').first().json.query || {};
const r = $input.first().json || {};
const page = (title, body) => `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#16201b;background:#f2f4f1}h1{font-size:22px}.card{background:#fff;border:1px solid #d6ddd7;border-radius:12px;padding:16px}button{font:inherit;padding:10px 18px;border-radius:8px;border:0;background:#2f6f4e;color:#fff;cursor:pointer}.muted{color:#5b6b62}</style></head><body>${body}</body></html>`;
if (!r.token) return [{ json: { html: page('Ссылка не найдена', '<h1>Ссылка не найдена</h1><p class="muted">Возможно, она устарела или скопирована не полностью.</p>') } }];
if (!r.valid) {
  const why = r.used_at ? 'Решение по этой ссылке уже принято' + (r.choice ? ': ' + esc(r.choice) : '') + '.' : (new Date(r.expires_at) < new Date() ? 'Срок ссылки истёк.' : 'Эксперимент сейчас не ждёт этого решения (статус ' + esc(r.status) + ', этап ' + r.exp_stage + ').');
  return [{ json: { html: page('Ссылка недействительна', `<h1>Ссылка недействительна</h1><p>${why}</p>`) } }];
}
const b = (r.briefs || []).find(x => x.slug === q.c) || { title: q.c };
const body = `<h1>${esc(r.exp_id)} · ${esc(r.gate)}</h1><div class="card"><p class="muted">Выбор брифа</p><p><b>${esc(b.title)}</b></p><p class="muted">канал ${esc(b.channel)} · CPC ~$${esc(b.cpc)} · цена ${esc(b.price)}</p>
<form method="post" action="https://n8n.home.kalik8s.ru/webhook/farm-gate"><input type="hidden" name="g" value="${esc(r.token)}"><input type="hidden" name="c" value="${esc(q.c)}"><button type="submit">Подтвердить выбор</button></form></div>
<p class="muted">Ссылка одноразовая. После подтверждения эксперимент перейдёт на этап ${r.stage + 1}.</p>`;
return [{ json: { html: page('Подтвердить выбор', body) } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json || {};
const ok = Number(r.applied) > 0;
const title = ok ? 'Принято' : 'Не принято';
const body = ok ? `<h1>Принято</h1><p>${esc(r.exp_id)} перешёл на этап ${r.stage}.</p>` : '<h1>Не принято</h1><p>Ссылка уже использована, устарела, или эксперимент сейчас не ждёт этого решения.</p>';
return [{ json: { ok, exp_id: r.exp_id, stage: r.stage, html: `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#16201b;background:#f2f4f1}h1{font-size:22px}.card{background:#fff;border:1px solid #d6ddd7;border-radius:12px;padding:16px}button{font:inherit;padding:10px 18px;border-radius:8px;border:0;background:#2f6f4e;color:#fff;cursor:pointer}.muted{color:#5b6b62}</style></head><body>${body}</body></html>` } }];
